import FluentKit
import Foundation

/// The "order_lines" table, as the database has it. Fluent never creates or changes it: the database already exists.
final class OrderLineModel: Model, @unchecked Sendable {
    static let schema = "order_lines"

    /// The key, a value of each of its columns.
    final class IDValue: Fields, Hashable, @unchecked Sendable {
        @Field(key: "order_id")
        var orderId: Int

        @Field(key: "line")
        var line: Int

        init() {}

        static func == (lhs: IDValue, rhs: IDValue) -> Bool {
            lhs.orderId == rhs.orderId && lhs.line == rhs.line
        }

        func hash(into hasher: inout Hasher) {
            hasher.combine(orderId)
            hasher.combine(line)
        }
    }

    @CompositeID()
    var id: IDValue?

    @Field(key: "product_id")
    var productId: Int

    @Field(key: "quantity")
    var quantity: Int

    init() {}
}

