import Foundation

/// Operations on products. Each write runs in its own transaction.
public struct ProductService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Product after checking it.
    @discardableResult
    public func createProduct(_ product: Product) async throws -> Product {
        let values = Values(categoryId: product.categoryId.map(Optional.some), name: product.name.map(Optional.some), price: product.price.map(Optional.some), status: product.status.map(Optional.some), version: product.version.map(Optional.some), deletedAt: product.deletedAt.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Product()
            applyValues(&entity, values)
            return try await uow.products.insert(entity)
        }
    }

    /// The Product with this key; notFound when there is none.
    public func getProduct(_ id: Int) async throws -> Product {
        try await find(unitOfWork, id)
    }

    /// A page of products, by primary key.
    public func listProducts(offset: Int, limit: Int) async throws -> Page<Product> {
        try await unitOfWork.products.list(offset: offset, limit: limit)
    }

    /// Changes the given values of a Product, read at version.
    @discardableResult
    public func updateProduct(_ id: Int, _ changes: ProductChanges, version: Int) async throws -> Product {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Product", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            current.version = version + 1
            return try await uow.products.update(current)
        }
    }

    /// Marks a Product as deleted (deleted_at); reads leave it out from then on.
    public func deleteProduct(_ id: Int, version: Int) async throws {
        try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Product", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            if !(try await uow.orderLines.listByProductId(current.id!)).isEmpty {
                throw DomainError.conflict(entity: "Product", reason: "rows of order_lines still point to it", fields: ["order_lines"])
            }
            current.deletedAt = Date()
            try await uow.products.update(current)
        }
    }

    /// The products with this category_id.
    public func listProductsByCategoryId(_ categoryId: Int) async throws -> [Product] {
        try await unitOfWork.products.listByCategoryId(categoryId)
    }

    /// Links a Product and a Tag (product_tags).
    public func addTag(_ productId: Int, _ tagId: Int) async throws {
        try await unitOfWork.transaction { uow in
            _ = try await find(uow, productId)
            if try await uow.tags.findById(tagId) == nil {
                throw DomainError.notFound(entity: "Tag", key: "\(tagId)")
            }
            if try await uow.productTags.findByProductIdAndTagId(productId, tagId) != nil {
                throw DomainError.conflict(entity: "Product", reason: "is already linked to this Tag", fields: ["tagId"])
            }
            try await uow.productTags.insert(ProductTag(productId: productId, tagId: tagId))
        }
    }

    /// Removes the link between a Product and a Tag (product_tags).
    public func removeTag(_ productId: Int, _ tagId: Int) async throws {
        try await unitOfWork.transaction { uow in
            guard let link = try await uow.productTags.findByProductIdAndTagId(productId, tagId) else {
                throw DomainError.notFound(entity: "ProductTag", key: "\(productId), \(tagId)")
            }
            try await uow.productTags.delete(link)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var categoryId: Int?? = nil
    var name: String?? = nil
    var price: Decimal?? = nil
    var status: String?? = nil
    var version: Int?? = nil
    var deletedAt: Date?? = nil
}

/// Checks the values against the rules of the "products" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Product?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if values.categoryId ?? nil == nil && (creating || values.categoryId != nil) {
        errors.append(FieldError("category_id", "is required"))
    }
    if let value = values.name ?? nil {
        if value.count > 100 {
            errors.append(FieldError("name", "is longer than 100 characters"))
        }
    } else if creating || values.name != nil {
        errors.append(FieldError("name", "is required"))
    }
    if let value = values.price ?? nil {
        if !(NSDecimalNumber(decimal: value).doubleValue >= 0.0) {
            errors.append(FieldError("price", "must be >= 0"))
        }
    } else if creating || values.price != nil {
        errors.append(FieldError("price", "is required"))
    }
    if let value = values.status ?? nil {
        if value.count > 10 {
            errors.append(FieldError("status", "is longer than 10 characters"))
        }
    } else if creating || values.status != nil {
        errors.append(FieldError("status", "is required"))
    }
    if values.version ?? nil == nil && (!creating && values.version != nil) {
        errors.append(FieldError("version", "cannot be empty"))
    }
    if let categoryId = values.categoryId ?? current?.categoryId {
        if try await uow.categories.findById(categoryId) == nil {
            errors.append(FieldError("category_id", "no Category has this key"))
        }
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Product", errors: errors) }
}

