fileprivate func applyValues(_ entity: inout Product, _ values: Values) {
    if let value = values.categoryId { entity.categoryId = value }
    if let value = values.name { entity.name = value }
    if let value = values.price { entity.price = value }
    if let value = values.status { entity.status = value }
    if let value = values.version { entity.version = value }
    if let value = values.deletedAt { entity.deletedAt = value }
}

