import Foundation

/// The values of a Tag that change: fields left .absent keep their value; .set(nil) empties one.
public struct TagChanges: Sendable {
    public var label: Patch<String?>

    public init(label: Patch<String?> = .absent) {
        self.label = label
    }
}

import Foundation

/// Operations on tags. Each write runs in its own transaction.
public struct TagService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Tag after checking it.
    @discardableResult
    public func createTag(_ tag: Tag) async throws -> Tag {
        let values = Values(label: tag.label.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Tag()
            applyValues(&entity, values)
            return try await uow.tags.insert(entity)
        }
    }

    /// The Tag with this key; notFound when there is none.
    public func getTag(_ id: Int) async throws -> Tag {
        try await find(unitOfWork, id)
    }

    /// A page of tags, by primary key.
    public func listTags(offset: Int, limit: Int) async throws -> Page<Tag> {
        try await unitOfWork.tags.list(offset: offset, limit: limit)
    }

    /// Changes the given values of a Tag.
    @discardableResult
    public func updateTag(_ id: Int, _ changes: TagChanges) async throws -> Tag {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await uow.tags.update(current)
        }
    }

    /// Deletes a Tag.
    public func deleteTag(_ id: Int) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.tags.delete(current)
        }
    }

    /// Links a Tag and a Product (product_tags).
    public func addProduct(_ tagId: Int, _ productId: Int) async throws {
        try await unitOfWork.transaction { uow in
            _ = try await find(uow, tagId)
            if try await uow.products.findById(productId) == nil {
                throw DomainError.notFound(entity: "Product", key: "\(productId)")
            }
            if try await uow.productTags.findByProductIdAndTagId(productId, tagId) != nil {
                throw DomainError.conflict(entity: "Tag", reason: "is already linked to this Product", fields: ["productId"])
            }
            try await uow.productTags.insert(ProductTag(productId: productId, tagId: tagId))
        }
    }

    /// Removes the link between a Tag and a Product (product_tags).
    public func removeProduct(_ tagId: Int, _ productId: Int) async throws {
        try await unitOfWork.transaction { uow in
            guard let link = try await uow.productTags.findByProductIdAndTagId(productId, tagId) else {
                throw DomainError.notFound(entity: "ProductTag", key: "\(productId), \(tagId)")
            }
            try await uow.productTags.delete(link)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var label: String?? = nil
}

/// Checks the values against the rules of the "tags" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Tag?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if let value = values.label ?? nil {
        if value.count > 30 {
            errors.append(FieldError("label", "is longer than 30 characters"))
        }
    } else if creating || values.label != nil {
        errors.append(FieldError("label", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Tag", errors: errors) }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Tag?) async throws {
    try await validate(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Tag, _ values: Values) {
    if let value = values.label { entity.label = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: TagChanges) -> Values {
    Values(label: changes.label.given)
}

/// The Tag with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: Int) async throws -> Tag {
    guard let row = try await uow.tags.findById(id) else {
        throw DomainError.notFound(entity: "Tag", key: "\(id)")
    }
    return row
}

import FluentKit

/// What services depend on: a repository per table and a transaction. Each service operation runs in transaction(): committed when it ends, rolled back when it throws.
public protocol UnitOfWork: Sendable {
    var customers: any CustomerRepository { get }
    var categories: any CategoryRepository { get }
    var products: any ProductRepository { get }
    var orders: any OrderRepository { get }
    var orderLines: any OrderLineRepository { get }
    var tags: any TagRepository { get }
    var productTags: any ProductTagRepository { get }
    var auditLog: any AuditLogRepository { get }

    /// Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws.
    func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T
}

/// The repositories over one database, and its transaction.
public struct SqlUnitOfWork: UnitOfWork {
    public let db: any Database

    public init(db: any Database) {
        self.db = db
    }

    public var customers: any CustomerRepository { SqlCustomerRepository(db: db) }

    public var categories: any CategoryRepository { SqlCategoryRepository(db: db) }

    public var products: any ProductRepository { SqlProductRepository(db: db) }

    public var orders: any OrderRepository { SqlOrderRepository(db: db) }

    public var orderLines: any OrderLineRepository { SqlOrderLineRepository(db: db) }

    public var tags: any TagRepository { SqlTagRepository(db: db) }

    public var productTags: any ProductTagRepository { SqlProductTagRepository(db: db) }

    public var auditLog: any AuditLogRepository { SqlAuditLogRepository(db: db) }

    /// Joins the transaction already open, or opens one.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await db.transaction { transaction in try await work(SqlUnitOfWork(db: transaction)) }
    }
}

/// The in-memory repositories, for tests and for trying the services without a database.
public final class MemoryUnitOfWork: UnitOfWork {
    public let customers: any CustomerRepository = MemoryCustomerRepository()
    public let categories: any CategoryRepository = MemoryCategoryRepository()
    public let products: any ProductRepository = MemoryProductRepository()
    public let orders: any OrderRepository = MemoryOrderRepository()
    public let orderLines: any OrderLineRepository = MemoryOrderLineRepository()
    public let tags: any TagRepository = MemoryTagRepository()
    public let productTags: any ProductTagRepository = MemoryProductTagRepository()
    public let auditLog: any AuditLogRepository = MemoryAuditLogRepository()

    public init() {}

    /// Memory has no transactions: changes are kept as they are made.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await work(self)
    }
}

